-- declare-kernel-boot-authority-rows.sql
--
-- The kernel boot's two declared authorities become rows. The data-access
-- authority (kernel/semantic-authority/consumer/
-- sda-node-boot-data-access.authority.v1.json) declares every read the Node boot
-- performs; the command-operations authority (kernel/semantic-authority/
-- consumer/sda-node-command-operations.authority.v1.json) declares the
-- carrier's operation vocabulary. Both are retained byte-for-byte in
-- source.content_object under their file SHA-256 and declared as selected
-- AUTHORITY semantic definitions whose semantics name the stable authority id,
-- the content digest and the original source path.
--
-- At runtime the kernel's data-access ground read
-- (SDA:languages/typescript/src/kernel/bootstrap/data-access.mjs, one fixed
-- statement) fetches the data-access authority from these rows, and the carrier
-- resolves the command vocabulary through the declared provider-authority read.
-- No repository path is dereferenced at runtime; the two files are removed.
--
-- Idempotent: content objects are content-addressed and the definition rows are
-- gated by their digests and declared ids.
--
-- Default: ROLLBACK. Replace the final ROLLBACK TRANSACTION; with COMMIT
-- TRANSACTION; to install after the from-transaction preflight passes.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @trigger_name nvarchar(517), @triggers CURSOR;
SET @triggers=CURSOR LOCAL FAST_FORWARD FOR
 SELECT QUOTENAME(s.name)+N'.'+QUOTENAME(t.name)
 FROM sys.triggers t JOIN sys.objects o ON o.object_id=t.parent_id
 JOIN sys.schemas s ON s.schema_id=o.schema_id
 WHERE o.type='U' AND s.name IN ('model','source')
 AND (t.name LIKE 'guard%' OR t.name LIKE '%immutable%');
OPEN @triggers;
FETCH NEXT FROM @triggers INTO @trigger_name;
WHILE @@FETCH_STATUS=0 BEGIN EXEC(N'DROP TRIGGER '+@trigger_name); FETCH NEXT FROM @triggers INTO @trigger_name; END;
CLOSE @triggers; DEALLOCATE @triggers;
GO

-- sda-node-boot-data-access.v1
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @object bigint,@definition bigint,@digest binary(32),@bytes varbinary(max),@content_digest binary(32);
SET @;
SET @content_digest=HASHBYTES('SHA2_256',@bytes);
IF LOWER(CONVERT(varchar(64),@content_digest,2))<>N'47b8897331a3946276ca3e9bc45288ef3c0c7218c0a485e16d3f50e84cb7ea12' THROW 51000,N'KERNEL_BOOT_AUTHORITY_DIGEST_MISMATCH:sda-node-boot-data-access.v1',1;
IF NOT EXISTS(SELECT 1 FROM source.content_object WHERE content_digest=@content_digest)
 INSERT source.content_object(content_digest,content_bytes,byte_length) VALUES(@content_digest,@bytes,DATALENGTH(@bytes));
IF (SELECT content_bytes FROM source.content_object WHERE content_digest=@content_digest)<>@bytes
 THROW 51000,N'KERNEL_BOOT_AUTHORITY_CONTENT_DIVERGED:sda-node-boot-data-access.v1',1;
EXEC model.put_semantic_definition 'AUTHORITY',N'sidefx:authorities',N'sda-node-boot-data-access.v1',N'{"authorityId":"sda-node-boot-data-access.v1","contentDigest":"sha256:47b8897331a3946276ca3e9bc45288ef3c0c7218c0a485e16d3f50e84cb7ea12","sourcePath":"kernel/semantic-authority/consumer/sda-node-boot-data-access.authority.v1.json","locators":["../scenario-driven-architecture/kernel/semantic-authority/consumer/sda-node-boot-data-access.authority.v1.json"]}',@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
IF NOT EXISTS (SELECT 1 FROM analysis.v_selected_semantic_definition d
 WHERE d.estate_model_pk=@estate AND d.object_kind='AUTHORITY' AND d.declared_id=N'sda-node-boot-data-access.v1'
  AND JSON_VALUE(d.definition_json,'$.semantics.contentDigest')=N'sha256:47b8897331a3946276ca3e9bc45288ef3c0c7218c0a485e16d3f50e84cb7ea12')
 THROW 51000,N'KERNEL_BOOT_AUTHORITY_DECLARATION_NOT_RESOLVED:sda-node-boot-data-access.v1',1;
IF NOT EXISTS (SELECT 1 FROM source.content_object co
 WHERE co.content_digest=@content_digest
  AND LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',co.content_bytes),2))=N'47b8897331a3946276ca3e9bc45288ef3c0c7218c0a485e16d3f50e84cb7ea12')
 THROW 51000,N'KERNEL_BOOT_AUTHORITY_CONTENT_NOT_RETAINED:sda-node-boot-data-access.v1',1;
GO

-- sda-node-command-operations.v1
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @object bigint,@definition bigint,@digest binary(32),@bytes varbinary(max),@content_digest binary(32);
SET @;
SET @content_digest=HASHBYTES('SHA2_256',@bytes);
IF LOWER(CONVERT(varchar(64),@content_digest,2))<>N'fc2ea2b696340113a28d985479c0619507b9f645c950f043175c63148bbe38ec' THROW 51000,N'KERNEL_BOOT_AUTHORITY_DIGEST_MISMATCH:sda-node-command-operations.v1',1;
IF NOT EXISTS(SELECT 1 FROM source.content_object WHERE content_digest=@content_digest)
 INSERT source.content_object(content_digest,content_bytes,byte_length) VALUES(@content_digest,@bytes,DATALENGTH(@bytes));
IF (SELECT content_bytes FROM source.content_object WHERE content_digest=@content_digest)<>@bytes
 THROW 51000,N'KERNEL_BOOT_AUTHORITY_CONTENT_DIVERGED:sda-node-command-operations.v1',1;
EXEC model.put_semantic_definition 'AUTHORITY',N'sidefx:authorities',N'sda-node-command-operations.v1',N'{"authorityId":"sda-node-command-operations.v1","contentDigest":"sha256:fc2ea2b696340113a28d985479c0619507b9f645c950f043175c63148bbe38ec","sourcePath":"kernel/semantic-authority/consumer/sda-node-command-operations.authority.v1.json","locators":["../scenario-driven-architecture/kernel/semantic-authority/consumer/sda-node-command-operations.authority.v1.json"]}',@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
IF NOT EXISTS (SELECT 1 FROM analysis.v_selected_semantic_definition d
 WHERE d.estate_model_pk=@estate AND d.object_kind='AUTHORITY' AND d.declared_id=N'sda-node-command-operations.v1'
  AND JSON_VALUE(d.definition_json,'$.semantics.contentDigest')=N'sha256:fc2ea2b696340113a28d985479c0619507b9f645c950f043175c63148bbe38ec')
 THROW 51000,N'KERNEL_BOOT_AUTHORITY_DECLARATION_NOT_RESOLVED:sda-node-command-operations.v1',1;
IF NOT EXISTS (SELECT 1 FROM source.content_object co
 WHERE co.content_digest=@content_digest
  AND LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',co.content_bytes),2))=N'fc2ea2b696340113a28d985479c0619507b9f645c950f043175c63148bbe38ec')
 THROW 51000,N'KERNEL_BOOT_AUTHORITY_CONTENT_NOT_RETAINED:sda-node-command-operations.v1',1;
GO

-- ============================== IN-TRANSACTION PREFLIGHT ==============================
-- The ground read statement is the exact fixed statement the kernel resolver
-- carries (SDA:languages/typescript/src/kernel/bootstrap/data-access.mjs). It
-- is executed here against the uncommitted rows; the declared provider-authority
-- read is then extracted from the retained data-access row and executed the
-- same way, and the vocabulary is checked member by member. Any red throws and
-- XACT_ABORT rolls the whole migration back.
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @ground nvarchar(max)=N'SELECT co.byte_length,
       LOWER(CONVERT(varchar(64),co.content_digest,2)) AS content_digest,
       co.content_bytes
FROM analysis.v_selected_semantic_definition d
JOIN source.content_object co
  ON co.content_digest=CONVERT(binary(32),REPLACE(JSON_VALUE(d.definition_json,''$.semantics.contentDigest''),''sha256:'',''''),2)
WHERE d.estate_model_pk=@estate_model_pk
  AND d.object_kind=''AUTHORITY''
  AND d.declared_id=N''sda-node-boot-data-access.v1''';
DECLARE @ground_authority TABLE (byte_length bigint, content_digest varchar(71), content_bytes varbinary(max));
INSERT @ground_authority EXEC sp_executesql @ground,N'@estate_model_pk bigint',@estate;

IF (SELECT COUNT_BIG(*) FROM @ground_authority)<>1 THROW 51000,N'KERNEL_BOOT_GROUND_READ_NOT_SINGULAR',1;
IF NOT EXISTS (SELECT 1 FROM @ground_authority WHERE content_digest=N'47b8897331a3946276ca3e9bc45288ef3c0c7218c0a485e16d3f50e84cb7ea12'
  AND LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',content_bytes),2))=N'47b8897331a3946276ca3e9bc45288ef3c0c7218c0a485e16d3f50e84cb7ea12')
 THROW 51000,N'KERNEL_BOOT_GROUND_READ_DIGEST_MISMATCH',1;
DECLARE @data_access_body nvarchar(max)=(SELECT CONVERT(nvarchar(max),CONVERT(varchar(max),content_bytes) COLLATE Latin1_General_100_BIN2_UTF8) FROM @ground_authority);
IF JSON_VALUE(@data_access_body,'$.authorityId')<>N'sda-node-boot-data-access.v1' THROW 51000,N'KERNEL_BOOT_GROUND_READ_ID_MISMATCH',1;
IF (SELECT COUNT(*) FROM OPENJSON(@data_access_body,'$.reads'))<6 THROW 51000,N'KERNEL_BOOT_GROUND_READ_READS_TRUNCATED',1;

DECLARE @provider_read nvarchar(max)=(SELECT JSON_VALUE(entry.value,'$.statement')
 FROM OPENJSON(@data_access_body,'$.reads') entry WHERE JSON_VALUE(entry.value,'$.readId')=N'provider-authority');
IF @provider_read IS NULL THROW 51000,N'KERNEL_BOOT_PROVIDER_AUTHORITY_READ_NOT_DECLARED',1;
DECLARE @vocabulary TABLE (declared_id nvarchar(400), authority_id nvarchar(400), platform_capability_id nvarchar(400),
 content_digest nvarchar(400), byte_length bigint, content_bytes varbinary(max));
INSERT @vocabulary EXEC sp_executesql @provider_read,N'@estate_model_pk bigint,@input nvarchar(max)',@estate,N'{"authorityId":"sda-node-command-operations.v1"}';
IF (SELECT COUNT_BIG(*) FROM @vocabulary)<>1 THROW 51000,N'KERNEL_BOOT_COMMAND_AUTHORITY_NOT_SINGULAR',1;
IF NOT EXISTS (SELECT 1 FROM @vocabulary WHERE content_digest=N'sha256:fc2ea2b696340113a28d985479c0619507b9f645c950f043175c63148bbe38ec'
  AND LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',content_bytes),2))=N'fc2ea2b696340113a28d985479c0619507b9f645c950f043175c63148bbe38ec')
 THROW 51000,N'KERNEL_BOOT_COMMAND_AUTHORITY_DIGEST_MISMATCH',1;
DECLARE @command_body nvarchar(max)=(SELECT CONVERT(nvarchar(max),CONVERT(varchar(max),content_bytes) COLLATE Latin1_General_100_BIN2_UTF8) FROM @vocabulary);
IF JSON_VALUE(@command_body,'$.authorityId')<>N'sda-node-command-operations.v1' THROW 51000,N'KERNEL_BOOT_COMMAND_AUTHORITY_ID_MISMATCH',1;
IF (SELECT COUNT(*) FROM OPENJSON(@command_body,'$.operations'))<>8 THROW 51000,N'KERNEL_BOOT_COMMAND_OPERATIONS_TRUNCATED',1;
IF NOT EXISTS (SELECT 1 FROM OPENJSON(@command_body,'$.operations') entry WHERE entry.[key]=N'invoke') THROW 51000,N'KERNEL_BOOT_COMMAND_OPERATION_NOT_DECLARED:invoke',1;
IF NOT EXISTS (SELECT 1 FROM OPENJSON(@command_body,'$.operations') entry WHERE entry.[key]=N'observe') THROW 51000,N'KERNEL_BOOT_COMMAND_OPERATION_NOT_DECLARED:observe',1;
IF NOT EXISTS (SELECT 1 FROM OPENJSON(@command_body,'$.operations') entry WHERE entry.[key]=N'circuit') THROW 51000,N'KERNEL_BOOT_COMMAND_OPERATION_NOT_DECLARED:circuit',1;
IF NOT EXISTS (SELECT 1 FROM OPENJSON(@command_body,'$.operations') entry WHERE entry.[key]=N'reveal') THROW 51000,N'KERNEL_BOOT_COMMAND_OPERATION_NOT_DECLARED:reveal',1;
IF NOT EXISTS (SELECT 1 FROM OPENJSON(@command_body,'$.operations') entry WHERE entry.[key]=N'catalogue') THROW 51000,N'KERNEL_BOOT_COMMAND_OPERATION_NOT_DECLARED:catalogue',1;
IF NOT EXISTS (SELECT 1 FROM OPENJSON(@command_body,'$.operations') entry WHERE entry.[key]=N'list') THROW 51000,N'KERNEL_BOOT_COMMAND_OPERATION_NOT_DECLARED:list',1;
IF NOT EXISTS (SELECT 1 FROM OPENJSON(@command_body,'$.operations') entry WHERE entry.[key]=N'find') THROW 51000,N'KERNEL_BOOT_COMMAND_OPERATION_NOT_DECLARED:find',1;
IF NOT EXISTS (SELECT 1 FROM OPENJSON(@command_body,'$.operations') entry WHERE entry.[key]=N'artifact') THROW 51000,N'KERNEL_BOOT_COMMAND_OPERATION_NOT_DECLARED:artifact',1;

SELECT '1_ground_read' AS result_set, declared_id, CONVERT(nvarchar(400),content_digest) AS content_digest, byte_length,
 (SELECT COUNT(*) FROM OPENJSON(@data_access_body,'$.reads')) AS read_count
FROM (
 SELECT N'sda-node-boot-data-access.v1' AS declared_id, content_digest, byte_length FROM @ground_authority
 UNION ALL
 SELECT N'sda-node-command-operations.v1', content_digest, byte_length FROM @vocabulary
) authority;

SELECT '2_command_vocabulary' AS result_set, entry.[key] AS operation
FROM OPENJSON(@command_body,'$.operations') entry ORDER BY entry.[key];

ROLLBACK TRANSACTION;
-- To install, replace the ROLLBACK above with COMMIT and re-run.
